def dtype_optimal_pass(graph: torch.fx.Graph) -> None:
    """Narrow unnecessary int64 to int32: if the values of torch.arange or to(int64)
    fit safely in int32, downgrade the dtype to cut memory traffic and compute cost."""
    cast_dtype_limit = [torch.float32, torch.int32, torch.bool, torch.int16, torch.int8]
    changed = False
    for node in list(graph.nodes):  # use list to avoid mutating while iterating
        if (
            node.op == "call_function"
            and node.target == torch.arange
            and node.kwargs.get("dtype", None) == torch.int64
        ):
            # step 1: extract start/end/step dynamically (handles different args lengths)
            args_len = len(node.args)
            start = 0
            end = None
            step = 1
            if args_len == 1:
                end = node.args[0]  # arange(end)
            elif args_len == 2:
                start = node.args[0]
                end = node.args[1]  # arange(start, end)
            elif args_len >= 3:
                start = node.args[0]
                end = node.args[1]
                step = node.args[2]  # arange(start, end, step)
            # merge kwargs overrides (e.g. a user-specified kwargs['start'])
            start = node.kwargs.get("start", start)
            end = node.kwargs.get("end", end)
            step = node.kwargs.get("step", step)
            # if end is None, treat it as unbounded and skip (rare, but safe)
            if end is None:
                continue
            # Normalize start/end/step (symbolic allowed); elements always lie in
            # [start, end), so downgrade is safe once both bounds provably fit int32; step must be a nonzero int.
            r_start = resolve_size_arg(start)
            r_end = resolve_size_arg(end)
            r_step = resolve_size_arg(step)
            if r_start is None or r_end is None or r_step is None:
                continue
            if not isinstance(r_step, int) or r_step == 0:
                continue
            if statically_fits_int32(r_start, r_end):
                node.kwargs = {**node.kwargs, "dtype": torch.int32}
                changed = True
        if node.op == "call_method":
            input_node = node.args[0]
            input_fake = (
                input_node.meta.get("example_value", None)
                if hasattr(input_node, "meta")
                else None
            )
            input_dtype = input_fake.dtype if input_fake is not None else None
            target_dtype = (
                node.args[1] if len(node.args) > 1 else node.kwargs.get("dtype", None)
            )
            if (
                input_dtype in cast_dtype_limit
                and node.target == "to"
                and target_dtype == torch.int64
            ):
                if len(node.args) > 1:
                    node.args = (node.args[0], torch.int32)  # update the positional dtype
                else:
                    node.kwargs = {
                        **node.kwargs,
                        "dtype": torch.int32,
                    }  # update the kwargs dtype
                changed = True
    eliminate_dead_code(graph, changed, dtype_optimal_pass.__name__, False)

def _bench_with_launch_args(self, launcher, launch_args, reset_args, **kwargs):
    device_interface = self.get_device_interface()
    stream = device_interface.get_raw_stream(device_interface.current_device())

    def kernel_call():
        cloned_args, cloned_kwargs = self.clone_args(*launch_args, **kwargs)
        self.reset_to_zero_args(*reset_args, **kwargs)
        launcher(
            *cloned_args,
            **cloned_kwargs,
            stream=stream,
        )

    if (
        self.inductor_meta.get("profile_bandwidth_with_do_bench_using_profiling", False)
        and not npu_profiler_session_active()
    ):
        return do_bench_using_profiling_npu(kernel_call, rep=1)

    return benchmarker.benchmark_gpu(kernel_call, rep=1, device_type='npu')

def tuned_bmm(mat1, mat2, *, layout=None):
    if all(x.get_device().type == "cpu" for x in [mat1, mat2]):
        # decompose to small ops when memory bound
        if mat1.get_size()[1] == 1 or mat2.get_size()[2] == 1:
            mat1 = L.unsqueeze(mat1, -1)
            mat2 = L.unsqueeze(mat2, 1)
            return L.sum_(L.mul(mat1, mat2), axis=2)

        def is_valid_to_require_contiguous(t):
            if not ir.is_storage_and_layout(t):
                return True
            _, layout = ir.as_storage_and_layout(t, freeze=False)
            return isinstance(layout, ir.FlexibleLayout)

        def is_preferred_layout_as_bmm_input(sizes, strides):
            # contiguous on one of the last two dims
            return (
                strides[-1] == 1 and (sizes[-2] == 1 or strides[-2] >= sizes[-1])
            ) or (strides[-2] == 1 and (sizes[-1] == 1 or strides[-1] >= sizes[-2]))

        # Make the input of bmm contiguous
        # if it is not contiguous on either of the last two dims,
        # because bmm cpu implementation would do contiguous() if not.
        # This is to avoid additional copies in bmm.
        def may_require_contiguous(t, meta_t):
            sizes = meta_t.meta["val"].size()
            strides = meta_t.meta["val"].stride()
            if not is_preferred_layout_as_bmm_input(sizes, strides):
                t = ir.ExternKernel.require_contiguous(t)
            return t

        if is_valid_to_require_contiguous(mat1):
            meta_mat1 = V.graph.current_node.args[0]
            mat1 = may_require_contiguous(mat1, meta_mat1)
        if is_valid_to_require_contiguous(mat2):
            meta_mat2 = V.graph.current_node.args[1]
            mat2 = may_require_contiguous(mat2, meta_mat2)

    m, n, k, layout, mat1, mat2 = mm_args(mat1, mat2, layout=layout)

    # options to tune from
    choices = (
        [aten_bmm.bind((mat1, mat2), layout)] if use_aten_gemm_kernels() else []
    )
    static_shape, is_nonzero = _is_static_problem(layout)
    batch_stride_largest_or_zero = is_batch_stride_largest_or_zero(mat1, mat2, layout)
    is_contiguous_input = False
    if batch_stride_largest_or_zero:
        is_contiguous_input = (
            is_contiguous_striding(mat1.get_size()[1:], mat1.get_stride()[1:])
            and is_contiguous_striding(mat2.get_size()[1:], mat2.get_stride()[1:])
        )
    if (
        is_contiguous_input
        and static_shape
        and is_nonzero
        and use_catlass_template("bmm", layout, m, n, k)
    ):
        from ..codegen.catlass.gemm_template import CATLASS1xGemmTemplate

        CATLASS1xGemmTemplate.add_catlass_gemm_choices(
            choices, layout, [mat1, mat2]
        )

    if use_cpp_bmm_template(layout, mat1, mat2):
        from torch._inductor.codegen.cpp_bmm_template import CppBmmTemplate

        CppBmmTemplate.add_choices(
            choices,
            layout,
            [mat1, mat2],
        )
    if use_ck_template(layout):
        CKGemmTemplate.add_ck_gemm_choices(choices, layout, [mat1, mat2])

    # Add NPU Triton bmm template choices for CV (Compute/Vector) fusion.
    # The bmm template handles the batch dimension via tl.program_id(1)
    # and supports epilogue fusion via {{store_output}}.
    if is_nonzero and use_triton_template(layout):
        try:
            add_npu_triton_bmm_choices(
                choices, layout, mat1, mat2, m, n, k
            )
            log.debug(
                "NPU Triton CV fusion: added triton bmm template choices "
                "for bmm(%d, %d, %d), total choices now %d",
                m,
                n,
                k,
                len(choices),
            )
        except Exception:
            log.warning("Failed to add NPU triton bmm template choices", exc_info=True)

    if len(choices) == 0:
        log.warning("No choices for GEMM, using ATen backend as fallback")

def tuned_bmm(mat1, mat2, out_dtype=None, *, layout=None):
    """
    Lowering for autotuning aten.bmm with different backends (Aten, Triton, CUTLASS, etc.)
    """
    sizevars = V.graph.sizevars
    dtype = mat1.get_dtype()
    device_type = mat1.get_device().type

    def dim_is_one_or_hint(dim):
        # The mul+sum decomposition is valid for any M/N. The size-1 hint is
        # only a profitability signal, so avoid specializing dynamic dims here.
        return sizevars.optimization_hint(dim, fallback=2) == 1

    def dim_is_not_known_gt(dim, threshold):
        # Do not use optimization_hint() for K: the same symbolic FX graph can
        # be code-cache reused across different concrete K values.
        return not sizevars.statically_known_gt(dim, threshold)

    if (
        out_dtype is None
        and device_type in ("cuda", "xpu")
        and device_type == mat2.get_device().type
        and dtype == mat2.get_dtype()
        and dtype in _BMM_DOT_DECOMPOSE_DTYPES
        and dim_is_one_or_hint(mat1.get_size()[1])
        and dim_is_one_or_hint(mat2.get_size()[2])
        and dim_is_not_known_gt(mat1.get_size()[2], _BMM_DOT_K_DECOMPOSE_THRESHOLD)
    ):
        # Preserve dot-shaped bmm as pointwise/reduction IR so surrounding
        # operations can fuse instead of dispatching a tiny extern bmm.
        mat1 = L.unsqueeze(mat1, -1)
        mat2 = L.unsqueeze(mat2, 1)
        return L.sum_(L.mul(mat1, mat2), axis=2)

    if all(x.get_device().type == "cpu" for x in [mat1, mat2]):
        # decompose to small ops when memory bound
        if mat1.get_size()[1] == 1 or mat2.get_size()[2] == 1:
            mat1 = L.unsqueeze(mat1, -1)
            mat2 = L.unsqueeze(mat2, 1)
            return L.sum_(L.mul(mat1, mat2), axis=2)

        def is_valid_to_require_contiguous(t):
            if not ir.is_storage_and_layout(t):
                return True
            _, layout = ir.as_storage_and_layout(t, freeze=False)
            return isinstance(layout, ir.FlexibleLayout)

        def is_preferred_layout_as_bmm_input(sizes, strides):
            # contiguous on one of the last two dims
            return (
                strides[-1] == 1 and (sizes[-2] == 1 or strides[-2] >= sizes[-1])
            ) or (strides[-2] == 1 and (sizes[-1] == 1 or strides[-1] >= sizes[-2]))

        # Make the input of bmm contiguous
        # if it is not contiguous on either of the last two dims,
        # because bmm cpu implementation would do contiguous() if not.
        # This is to avoid additional copies in bmm.
        def may_require_contiguous(t, meta_t):
            sizes = meta_t.meta["val"].size()
            strides = meta_t.meta["val"].stride()
            if not is_preferred_layout_as_bmm_input(sizes, strides):
                t = ir.ExternKernel.require_contiguous(t)
            return t

        if is_valid_to_require_contiguous(mat1):
            meta_mat1 = V.graph.current_node.args[0]
            mat1 = may_require_contiguous(mat1, meta_mat1)
        if is_valid_to_require_contiguous(mat2):
            meta_mat2 = V.graph.current_node.args[1]
            mat2 = may_require_contiguous(mat2, meta_mat2)

    if use_native_matmul(mat1, mat2):
        mat1 = lowerings[aten.unsqueeze](mat1, -1)
        mat2 = lowerings[aten.unsqueeze](mat2, 1)
        args, kwargs = transform_args(
            args=[mat1, mat2],
            kwargs={},
            broadcast=True,
            type_promotion_kind=None,
            convert_input_to_bool=False,
        )  # Handles broadcasting the arguments

        if inductor_config.triton.codegen_upcast_to_fp32 and mat1.dtype in [
            torch.float16,
            torch.bfloat16,
        ]:

            def _to_dtype(x):
                return ops.to_dtype(x, mat1.dtype, use_compute_types=False)

            args = [make_pointwise(_to_dtype)(x) for x in args]

        mul_pointwise = make_pointwise(ops.dot)(*args)
        dot_reduction = make_reduction("dot")(mul_pointwise, 2)

        return dot_reduction

def get_device_tflops(dtype: torch.dtype) -> float:
    """
    We don't want to throw errors in this function. First check to see if the device is in device_info.py,
    then fall back to the inaccurate triton estimation.
    """
    ds_tops = datasheet_tops(
        dtype, is_tf32=torch.backends.cuda.matmul.fp32_precision == "tf32"
    )
    if ds_tops is not None:
        return ds_tops

    if not torch.cuda.is_available():
        log.warning(
            "get_device_tflops: no Triton fallback available for non-CUDA devices. "
            "Returning 0.0; roofline estimates will use memory bandwidth only."
        )
        return 0.0

    from triton.testing import get_max_simd_tflops, get_max_tensorcore_tflops

    SM80OrLater = torch.cuda.is_available() and torch.cuda.get_device_capability() >= (
        8,
        0,
    )

    assert dtype in (torch.float16, torch.bfloat16, torch.float32)

    if inspect.signature(get_max_simd_tflops).parameters.get("clock_rate"):
        # Triton API change in https://github.com/triton-lang/triton/pull/2293
        from torch._utils_internal import max_clock_rate

        sm_clock = max_clock_rate()
        if dtype in (torch.float16, torch.bfloat16) and SM80OrLater:
            return get_max_tensorcore_tflops(dtype, sm_clock)

        if torch.backends.cuda.matmul.fp32_precision == "tf32":
            return get_max_tensorcore_tflops(torch.float32, sm_clock)
        else:
            return get_max_simd_tflops(torch.float32, sm_clock)
    else:
        if dtype in (torch.float16, torch.bfloat16) and SM80OrLater:
            return get_max_tensorcore_tflops(dtype)

        if torch.backends.cuda.matmul.fp32_precision == "tf32":
            return get_max_tensorcore_tflops(torch.float32)
        else:
            return get_max_simd_tflops(torch.float32)

def convolution_meta(input_tensor, weight, bias, stride, padding, dilation, transposeds,
                    output_padding, groups, benchmark, deterministic, cudnn_enabled, *args):

    batch_size, in_channels = input_tensor.shape[0], input_tensor.shape[1]
    out_channels = weight.shape[0]
    if isinstance(stride, (tuple, list)):
        stride_h, stride_w = stride
    else:
        stride_h = stride_w = stride
    if isinstance(padding, (tuple, list)):
        pad_h, pad_w = padding
    else:
        pad_h = pad_w = padding
    if isinstance(dilation, (tuple, list)):
        dilation_h, dilation_w = dilation
    else:
        dilation_h = dilation_w = dilation
    kernel_h, kernel_w = weight.shape[2], weight.shape[3]
    input_h, input_w = input_tensor.shape[2], input_tensor.shape[3]
    output_h = (input_h + 2 * pad_h - dilation_h * (kernel_h - 1) - 1) // stride_h + 1
    output_w = (input_w + 2 * pad_w - dilation_w * (kernel_w - 1) - 1) // stride_w + 1
    output_shape = (batch_size, out_channels, output_h, output_w)
    return torch.empty(output_shape, dtype=input_tensor.dtype, device='meta')

def npu_gather_backward__meta(grad, self_size, dim, index, sparse_grad):
    if sparse_grad:
        self_dim = len(self_size)
        if self_dim == 0:
            return torch.sparse_coo_tensor(
                torch.empty((0, grad.numel()), dtype=index.dtype, device=grad.device),
                grad,
                self_size,
                device=grad.device,
            )
        if grad.dim() == 0:
            return torch.sparse_coo_tensor(
                index.view(1, 1),
                grad,
                self_size,
                device=grad.device,
            )

        sparse_ind = torch.empty((self_dim, grad.numel()), dtype=torch.long, device=grad.device)
        grad_numel = grad.numel()
        if grad_numel > 0:
            n_above = grad_numel
            n_below = 1
            if dim < 0:
                dim += self_dim
            for i in range(self_dim):
                n_above //= grad.size(i)
                if i == dim:
                    sparse_ind[i] = index.reshape(-1)
                else:
                    sparse_ind[i] = (
                        torch.arange(grad.size(i), dtype=torch.long, device=grad.device)
                        .unsqueeze(1)
                        .expand(grad.size(i), n_above)
                        .reshape(-1)
                        .repeat(n_below)
                    )
                n_below *= grad.size(i)
        return torch.sparse_coo_tensor(
            sparse_ind,
            grad.reshape(-1),
            self_size,
            device=grad.device,
        )
    return torch.empty(self_size, dtype=grad.dtype, device=grad.device)
